/**
 * @param {Function} fn
 * @param {Array} args
 * @param {number} t
 * @return {Function}
 */
var cancellable = function(fn, args, t) {
    // Schedule fn(...args) after t ms and keep the timer id in the closure
    const timerId = setTimeout(() => fn(...args), t);

    // cancelFn: clearing an already-fired or already-cleared timer is a harmless no-op
    return function cancelFn() {
        clearTimeout(timerId);
    };
};
